from functools import lru_cache
class Solution:
    def minimumCost(self, source: str, target: str, rules: List[List[str]], costs: List[int]) -> int:
        n = len(source)
        info = [(r[0], r[1], c, r[0].count('*')) for r, c in zip(rules, costs)]
        @lru_cache(maxsize=None)
        def f(l):
            if l == n:
                return 0
            best = float('inf')
            for p, rep, c, w in info:
                L = len(p)
                if l + L > n:
                    continue
                ok = True
                for j in range(L):
                    if p[j] != '*' and p[j] != source[l + j]:
                        ok = False
                        break
                    if rep[j] != target[l + j]:
                        ok = False
                        break
                if ok:
                    sub = f(l + L)
                    if sub < best - c - w:
                        best = min(best, c + w + sub)
            return best
        ans = f(0)
        return ans if ans != float('inf') else -1

