class Solution {
public:
    long long minimumCost(string source, string target, vector<vector<string>>& rules, vector<int>& costs) {
        int n = source.size();
        int R = rules.size();
        vector<long long> memo(n + 1, -1);
        function<long long(int)> f = [&](int l) -> long long {
            if (l == n) return 0;
            if (memo[l] != -1) return memo[l];
            long long best = LLONG_MAX;
            for (int i = 0; i < R; i++) {
                const string& p = rules[i][0];
                const string& rep = rules[i][1];
                int L = p.size();
                if (l + L > n) continue;
                bool ok = true;
                int w = 0;
                for (int j = 0; j < L && ok; j++) {
                    if (p[j] == '*') w++;
                    else if (p[j] != source[l + j]) ok = false;
                    if (ok && rep[j] != target[l + j]) ok = false;
                }
                if (!ok) continue;
                long long sub = f(l + L);
                if (sub != LLONG_MAX) best = min(best, (long long)costs[i] + w + sub);
            }
            return memo[l] = best;
        };
        long long ans = f(0);
        return ans == LLONG_MAX ? -1 : ans;
    }
};

