class Solution {
    private String source, target;
    private List<List<String>> rules;
    private int[] costs;
    private Long[] memo;

    public long minimumCost(String source, String target, List<List<String>> rules, int[] costs) {
        this.source = source; this.target = target;
        this.rules = rules; this.costs = costs;
        memo = new Long[source.length() + 1];
        long ans = f(0);
        return ans == Long.MAX_VALUE ? -1 : ans;
    }

    private long f(int l) {
        if (l == source.length()) return 0;
        if (memo[l] != null) return memo[l];
        long best = Long.MAX_VALUE;
        for (int i = 0; i < rules.size(); i++) {
            String p = rules.get(i).get(0), rep = rules.get(i).get(1);
            int L = p.length();
            if (l + L > source.length()) continue;
            boolean ok = true;
            int w = 0;
            for (int j = 0; j < L && ok; j++) {
                if (p.charAt(j) == '*') w++;
                else if (p.charAt(j) != source.charAt(l + j)) ok = false;
                if (ok && rep.charAt(j) != target.charAt(l + j)) ok = false;
            }
            if (!ok) continue;
            long sub = f(l + L);
            if (sub != Long.MAX_VALUE) best = Math.min(best, costs[i] + w + sub);
        }
        return memo[l] = best;
    }
}

