class Solution {
public:
    long long minimumCost(string source, string target, vector<vector<string>>& rules, vector<int>& costs) {
        int n = source.size(), R = rules.size();
        const long long INF = LLONG_MAX / 2;
        vector<int> len(R), wc(R);
        vector<vector<pair<int,char>>> fixed(R);
        for (int i = 0; i < R; i++) {
            const string& p = rules[i][0];
            len[i] = p.size();
            wc[i] = count(p.begin(), p.end(), '*');
            for (int j = 0; j < len[i]; j++)
                if (p[j] != '*') fixed[i].push_back({j, p[j]});
        }
        vector<long long> dp(n + 1, INF);
        dp[0] = 0;
        for (int l = 0; l < n; l++) {
            if (dp[l] >= INF) continue;
            for (int i = 0; i < R; i++) {
                int e = l + len[i];
                if (e > n) continue;
                bool ok = true;
                for (auto& [j, ch] : fixed[i])
                    if (source[l + j] != ch) { ok = false; break; }
                if (ok) {
                    const string& rep = rules[i][1];
                    for (int j = 0; j < len[i]; j++)
                        if (rep[j] != target[l + j]) { ok = false; break; }
                }
                if (ok) dp[e] = min(dp[e], dp[l] + costs[i] + wc[i]);
            }
        }
        return dp[n] >= INF ? -1 : dp[n];
    }
};

