class Solution {
    public long minimumCost(String source, String target, List<List<String>> rules, int[] costs) {
        int n = source.length(), R = rules.size();
        long INF = Long.MAX_VALUE / 2;
        int[] len = new int[R], wc = new int[R];
        List<List<int[]>> fixed = new ArrayList<>();
        for (int i = 0; i < R; i++) {
            String p = rules.get(i).get(0);
            len[i] = p.length();
            List<int[]> fx = new ArrayList<>();
            for (int j = 0; j < len[i]; j++) {
                if (p.charAt(j) == '*') wc[i]++;
                else fx.add(new int[]{j, p.charAt(j)});
            }
            fixed.add(fx);
        }
        long[] dp = new long[n + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int l = 0; l < n; l++) {
            if (dp[l] >= INF) continue;
            for (int i = 0; i < R; i++) {
                int e = l + len[i];
                if (e > n) continue;
                boolean ok = true;
                for (int[] fc : fixed.get(i))
                    if (source.charAt(l + fc[0]) != fc[1]) { ok = false; break; }
                if (ok) {
                    String rep = rules.get(i).get(1);
                    for (int j = 0; j < len[i]; j++)
                        if (rep.charAt(j) != target.charAt(l + j)) { ok = false; break; }
                }
                if (ok) dp[e] = Math.min(dp[e], dp[l] + costs[i] + wc[i]);
            }
        }
        return dp[n] >= INF ? -1 : dp[n];
    }
}

