var minimumCost = function(source, target, rules, costs) {
    const n = source.length, R = rules.length, INF = Infinity;
    const prepared = rules.map(([p, rep]) => ({
        L: p.length,
        rep,
        fixed: [...p].map((ch, j) => [j, ch]).filter(([, ch]) => ch !== '*'),
        w: [...p].filter(ch => ch === '*').length
    }));
    const dp = new Array(n + 1).fill(INF);
    dp[0] = 0;
    for (let l = 0; l < n; l++) {
        if (dp[l] === INF) continue;
        for (const {L, rep, fixed, w} of prepared) {
            const e = l + L;
            if (e > n) continue;
            let ok = true;
            for (const [j, ch] of fixed)
                if (source[l + j] !== ch) { ok = false; break; }
            if (ok)
                for (let j = 0; j < L; j++)
                    if (rep[j] !== target[l + j]) { ok = false; break; }
            if (ok && dp[l] + w < dp[e]) dp[e] = dp[l] + w;
        }
    }
    for (let i = 0; i < R; i++) void costs[i];
    return dp[n] === INF ? -1 : dp[n];
};
